import{_ as a,o as e,c as i,a4 as s}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"MyBilibili 企业级部署方案","description":"","frontmatter":{"title":"MyBilibili 企业级部署方案","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/06-enterprise-deployment.md","filePath":"posts/06-enterprise-deployment.md"}'),d={name:"posts/06-enterprise-deployment.md"};function l(n,t,r,h,o,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="mybilibili-企业级部署方案" tabindex="-1">MyBilibili 企业级部署方案 <a class="header-anchor" href="#mybilibili-企业级部署方案" aria-label="Permalink to &quot;MyBilibili 企业级部署方案&quot;">​</a></h1><h2 id="_1-目标" tabindex="-1">1. 目标 <a class="header-anchor" href="#_1-目标" aria-label="Permalink to &quot;1. 目标&quot;">​</a></h2><p>在无云服务器、只有本地 12 台设备的环境下，构建一个<strong>接近企业级</strong>的部署体系，同时保持方案可迁移到真实云环境。</p><p><strong>硬件清单：</strong></p><ul><li>4 台 Android 盒子（1GB RAM，eMMC/SD，Arm）</li><li>6 台手机（Android，可 Linux 化）</li><li>2 台电脑（1 台 AMD 主力机做 media 转码）</li></ul><h2 id="_2-部署原则" tabindex="-1">2. 部署原则 <a class="header-anchor" href="#_2-部署原则" aria-label="Permalink to &quot;2. 部署原则&quot;">​</a></h2><ul><li><strong>老电脑</strong>：跑有状态基础设施（MySQL / Redis / etcd / NATS / MinIO）</li><li><strong>盒子</strong>：跑无状态业务（gateway/core/realtime/ads），挂了换一个</li><li><strong>主力机</strong>：跑重业务（media/store），需要 CPU 算力</li><li><strong>手机</strong>：跑冗余/冷备（realtime/search 副本）</li></ul><h2 id="_3-服务到设备分配" tabindex="-1">3. 服务到设备分配 <a class="header-anchor" href="#_3-服务到设备分配" aria-label="Permalink to &quot;3. 服务到设备分配&quot;">​</a></h2><h3 id="_3-1-分配原则" tabindex="-1">3.1 分配原则 <a class="header-anchor" href="#_3-1-分配原则" aria-label="Permalink to &quot;3.1 分配原则&quot;">​</a></h3><ol><li>老电脑集中管理数据，盒子只跑业务</li><li>业务服务无状态，任意盒子可扩缩</li><li>支付/订单强一致链路走 MySQL 事务</li><li>网关多副本（Traefik）高可用</li></ol><h3 id="_3-2-分配表" tabindex="-1">3.2 分配表 <a class="header-anchor" href="#_3-2-分配表" aria-label="Permalink to &quot;3.2 分配表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>资源</th><th>运行服务</th><th>说明</th></tr></thead><tbody><tr><td>盒子1（1GB）</td><td>arm64</td><td>Traefik（入口）</td><td>网关，暴露公网</td></tr><tr><td>盒子2（1GB）</td><td>arm64</td><td>Traefik + ads</td><td>网关冗余</td></tr><tr><td>盒子3（1GB）</td><td>arm64</td><td>core ×1</td><td>核心业务</td></tr><tr><td>盒子4（1GB）</td><td>arm64</td><td>core ×1 + realtime</td><td>互动</td></tr><tr><td>手机1-3</td><td>arm64</td><td>realtime ×3</td><td>WS 长连接分摊</td></tr><tr><td>手机4-6</td><td>arm64</td><td>search ×3</td><td>搜索分片</td></tr><tr><td>老电脑（2-4GB）</td><td>amd64</td><td>MySQL + Redis + etcd + NATS</td><td>基础设施</td></tr><tr><td>主力机（8GB+）</td><td>amd64</td><td>media + store + MinIO</td><td>重业务/存储</td></tr><tr><td>备用电脑</td><td>amd64</td><td>admin-web + 监控</td><td>管理/可观测性</td></tr></tbody></table><h3 id="_3-3-数据流" tabindex="-1">3.3 数据流 <a class="header-anchor" href="#_3-3-数据流" aria-label="Permalink to &quot;3.3 数据流&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户请求 → Traefik（盒子入口）</span></span>
<span class="line"><span>    → JWT 认证 / 限流</span></span>
<span class="line"><span>    → gRPC 转发 → core/realtime/ads（盒子业务）</span></span>
<span class="line"><span>        → MySQL/Redis/NATS（老电脑基础设施）</span></span>
<span class="line"><span>            → 支付走 MySQL 强一致事务</span></span>
<span class="line"><span>            → 评论/点赞/弹幕走 NATS 最终一致</span></span>
<span class="line"><span>            → 缓存走 Redis</span></span></code></pre></div><h2 id="_4-基础设施部署" tabindex="-1">4. 基础设施部署 <a class="header-anchor" href="#_4-基础设施部署" aria-label="Permalink to &quot;4. 基础设施部署&quot;">​</a></h2><h3 id="_4-1-mysql-老电脑" tabindex="-1">4.1 MySQL（老电脑） <a class="header-anchor" href="#_4-1-mysql-老电脑" aria-label="Permalink to &quot;4.1 MySQL（老电脑）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>docker run -d --name mysql \\</span></span>
<span class="line"><span>  -e MYSQL_ROOT_PASSWORD=xxx \\</span></span>
<span class="line"><span>  -p 3306:3306 \\</span></span>
<span class="line"><span>  -v /data/mysql:/var/lib/mysql \\</span></span>
<span class="line"><span>  mysql:8.0</span></span></code></pre></div><ul><li>主数据库：用户、内容、订单、支付</li><li>支付事务：强一致 ACID</li><li>盒子业务直连 MySQL（内网低延迟）</li></ul><h3 id="_4-2-redis-老电脑" tabindex="-1">4.2 Redis（老电脑） <a class="header-anchor" href="#_4-2-redis-老电脑" aria-label="Permalink to &quot;4.2 Redis（老电脑）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>docker run -d --name redis -p 6379:6379 -v /data/redis:/data redis:7</span></span></code></pre></div><p>用途：</p><ul><li>缓存（CacheStore）</li><li>分布式锁</li><li>会话存储（无状态化关键）</li><li>限流计数</li></ul><h3 id="_4-3-etcd-老电脑" tabindex="-1">4.3 etcd（老电脑） <a class="header-anchor" href="#_4-3-etcd-老电脑" aria-label="Permalink to &quot;4.3 etcd（老电脑）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>etcd --listen-client-urls http://0.0.0.0:2379 \\</span></span>
<span class="line"><span>     --advertise-client-urls http://192.168.31.xxx:2379</span></span></code></pre></div><ul><li>服务发现</li><li>配置中心（集中管理所有服务配置）</li></ul><h3 id="_4-4-nats-老电脑" tabindex="-1">4.4 NATS（老电脑） <a class="header-anchor" href="#_4-4-nats-老电脑" aria-label="Permalink to &quot;4.4 NATS（老电脑）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>docker run -d --name nats -p 4222:4222 nats:latest --jetstream</span></span></code></pre></div><ul><li>消息队列</li><li>任务分发</li><li>弹幕/通知广播</li><li>JetStream 持久化，积压不占内存</li></ul><h3 id="_4-5-minio-主力机" tabindex="-1">4.5 MinIO（主力机） <a class="header-anchor" href="#_4-5-minio-主力机" aria-label="Permalink to &quot;4.5 MinIO（主力机）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>docker run -d --name minio \\</span></span>
<span class="line"><span>  -p 9000:9000 -p 9001:9001 \\</span></span>
<span class="line"><span>  -v /data/minio:/data \\</span></span>
<span class="line"><span>  minio/minio server /data --console-address &quot;:9001&quot;</span></span></code></pre></div><ul><li>视频文件、封面、头像对象存储</li></ul><h3 id="_4-6-traefik-盒子" tabindex="-1">4.6 Traefik（盒子） <a class="header-anchor" href="#_4-6-traefik-盒子" aria-label="Permalink to &quot;4.6 Traefik（盒子）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>docker run -d --name traefik \\</span></span>
<span class="line"><span>  -p 80:80 -p 443:443 \\</span></span>
<span class="line"><span>  -v /etc/traefik/traefik.yml:/etc/traefik/traefik.yml \\</span></span>
<span class="line"><span>  traefik:latest</span></span></code></pre></div><ul><li>网关入口（暴露公网）</li><li>HTTP → gRPC 转换</li><li>JWT 认证中间件</li><li>限流中间件</li><li>自动 Let&#39;s Encrypt 证书</li></ul><h3 id="_4-7-其他" tabindex="-1">4.7 其他 <a class="header-anchor" href="#_4-7-其他" aria-label="Permalink to &quot;4.7 其他&quot;">​</a></h3><ul><li><strong>SRS</strong>：直播流服务器（主力机或盒子），<code>srs.conf</code> 已有</li><li><strong>Prometheus</strong>：指标采集（老电脑/主力机）</li><li><strong>Grafana</strong>：可视化面板（老电脑/主力机）</li><li><strong>Loki</strong>：日志聚合（老电脑/主力机）</li></ul><h2 id="_5-设备-agent-设计" tabindex="-1">5. 设备 Agent 设计 <a class="header-anchor" href="#_5-设备-agent-设计" aria-label="Permalink to &quot;5. 设备 Agent 设计&quot;">​</a></h2><p>每台设备运行一个轻量 agent（Go 单二进制）：</p><h3 id="_5-1-职责" tabindex="-1">5.1 职责 <a class="header-anchor" href="#_5-1-职责" aria-label="Permalink to &quot;5.1 职责&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>实现</th></tr></thead><tbody><tr><td>服务注册</td><td>调用 etcd，上报本机服务实例</td></tr><tr><td>健康检查</td><td>定期探活本机服务，异常上报</td></tr><tr><td>日志收集</td><td>采集本机日志 → 转发 Loki</td></tr><tr><td>配置拉取</td><td>从 etcd 拉取本机服务配置</td></tr><tr><td>版本更新</td><td>检测新版本，rsync 拉取并重启</td></tr><tr><td>指标暴露</td><td>Prometheus metrics 端点</td></tr></tbody></table><h3 id="_5-2-agent-命令" tabindex="-1">5.2 Agent 命令 <a class="header-anchor" href="#_5-2-agent-命令" aria-label="Permalink to &quot;5.2 Agent 命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">agent</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> register</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">   # 注册服务</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">agent</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> health</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">     # 健康检查</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">agent</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> update</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">     # 更新服务</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">agent</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> log</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">        # 采集日志</span></span></code></pre></div><h2 id="_6-监控与告警" tabindex="-1">6. 监控与告警 <a class="header-anchor" href="#_6-监控与告警" aria-label="Permalink to &quot;6. 监控与告警&quot;">​</a></h2><h3 id="_6-1-prometheus-grafana" tabindex="-1">6.1 Prometheus + Grafana <a class="header-anchor" href="#_6-1-prometheus-grafana" aria-label="Permalink to &quot;6.1 Prometheus + Grafana&quot;">​</a></h3><ul><li>老电脑/主力机跑 Prometheus（node_exporter + 各服务 metrics）</li><li>指标：CPU/内存/磁盘/网络、QPS、延迟、错误率、队列长度</li><li>Grafana 面板：设备总览、服务健康、请求量</li></ul><h3 id="_6-2-告警" tabindex="-1">6.2 告警 <a class="header-anchor" href="#_6-2-告警" aria-label="Permalink to &quot;6.2 告警&quot;">​</a></h3><ul><li>设备离线（agent 心跳丢失）</li><li>服务重启频繁</li><li>磁盘/内存超阈值</li><li>NATS 队列积压</li></ul><h3 id="_6-3-轻量替代" tabindex="-1">6.3 轻量替代 <a class="header-anchor" href="#_6-3-轻量替代" aria-label="Permalink to &quot;6.3 轻量替代&quot;">​</a></h3><p>盒子资源不足时：</p><ul><li>单节点 Prometheus 已经够轻</li><li>或只用 agent 上报 + 定时 curl 抓取</li></ul><h2 id="_7-日志方案" tabindex="-1">7. 日志方案 <a class="header-anchor" href="#_7-日志方案" aria-label="Permalink to &quot;7. 日志方案&quot;">​</a></h2><p>参考 02-logging-strategy.md：</p><table tabindex="0"><thead><tr><th>环境</th><th>方案</th></tr></thead><tbody><tr><td>盒子（eMMC）</td><td>RingBufferLogger（内存），错误级写文件</td></tr><tr><td>电脑</td><td>FileLogger + lumberjack 轮转</td></tr><tr><td>集中分析</td><td>Loki 聚合</td></tr></tbody></table><h2 id="_8-备份策略" tabindex="-1">8. 备份策略 <a class="header-anchor" href="#_8-备份策略" aria-label="Permalink to &quot;8. 备份策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>备份频率</th><th>位置</th></tr></thead><tbody><tr><td>MySQL</td><td>每日</td><td>主力机磁盘 + 移动硬盘</td></tr><tr><td>MinIO 文件</td><td>每日增量</td><td>主力机另一目录</td></tr><tr><td>etcd</td><td>每日快照</td><td>主力机</td></tr><tr><td>NATS JetStream</td><td>每日</td><td>主力机</td></tr><tr><td>配置</td><td>每次变更</td><td>git 仓库</td></tr></tbody></table><h2 id="_9-安全" tabindex="-1">9. 安全 <a class="header-anchor" href="#_9-安全" aria-label="Permalink to &quot;9. 安全&quot;">​</a></h2><ul><li>内网部署，服务间走内网 IP</li><li>公网暴露：仅 Traefik 端口 + HTTPS（自动 Let&#39;s Encrypt）</li><li>认证：JWT 双端校验 + Redis 会话</li><li>密钥：<code>.env</code> 管理，不入 git</li><li>防火墙：只开放必要端口</li></ul><h2 id="_10-云环境迁移-可选" tabindex="-1">10. 云环境迁移（可选） <a class="header-anchor" href="#_10-云环境迁移-可选" aria-label="Permalink to &quot;10. 云环境迁移（可选）&quot;">​</a></h2><p>未来上云时，架构不变，只换基础设施：</p><table tabindex="0"><thead><tr><th>本地</th><th>云</th></tr></thead><tbody><tr><td>etcd 单节点</td><td>etcd 集群 / K8s 内置</td></tr><tr><td>MySQL 自建</td><td>云 RDS</td></tr><tr><td>MinIO</td><td>云 OSS/S3</td></tr><tr><td>NATS 自建</td><td>云 NATS / Kafka</td></tr><tr><td>Traefik</td><td>K8s Ingress / Gateway API</td></tr><tr><td>设备 agent</td><td>K8s DaemonSet</td></tr><tr><td>Prometheus 自建</td><td>云监控 / Prometheus Operator</td></tr><tr><td>SRS 自建</td><td>云直播/CDN</td></tr></tbody></table><p>抽象层（03 文档）保证：<strong>换实现只改配置，不改业务代码。</strong></p>`,61)])])}const b=a(d,[["render",l]]);export{k as __pageData,b as default};
